@Nullable
public static Signature[] getAppSignatures(final String packageName) {
    if (UtilsBridge.isSpace(packageName)) return null;
    try {
        PackageManager pm = Utils.getApp().getPackageManager();
        return getSignaturesFromPackageInfo(pm.getPackageInfo(packageName, getSignatureFlags()));
    } catch (PackageManager.NameNotFoundException e) {
        e.printStackTrace();
        return null;
    }
}

private static int getSignatureFlags() {
    return Build.VERSION.SDK_INT >= Build.VERSION_CODES.P
            ? PackageManager.GET_SIGNING_CERTIFICATES
            : PackageManager.GET_SIGNATURES;
}

@Nullable
private static Signature[] getSignaturesFromPackageInfo(final PackageInfo pi) {
    if (pi == null) return null;
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
        SigningInfo signingInfo = pi.signingInfo;
        if (signingInfo.hasMultipleSigners()) {
            return signingInfo.getApkContentsSigners();
        } else {
            return signingInfo.getSigningCertificateHistory();
        }
    } else {
        return pi.signatures;
    }
}

/**
 * Return the application's signature.
 *
 * @param file The file.
 * @return the application's signature
 */
@Nullable
public static Signature[] getAppSignatures(final File file) {
    if (file == null) return null;
    PackageManager pm = Utils.getApp().getPackageManager();
    return getSignaturesFromPackageInfo(pm.getPackageArchiveInfo(file.getAbsolutePath(), getSignatureFlags()));

